  C = `#include <stdio.h>

int sum_to(int n) {
  int i;
  int total;
  total = 0;
  for (i = 1; i <= n; i++) {
    total = total + i;
  }
  return total;
}

int main() {
  int n;
  int got;
  got = scanf("%d", &n);
  if (got != 1) {
    n = 10;
  }
  printf("sum 1..%d = %d\\n", n, sum_to(n));
  return 0;
}
`,
  CPP = `#include <iostream>
using namespace std;

int clamp(int value, int low, int high) {
  if (value < low) return low;
  if (value > high) return high;
  return value;
}

int main() {
  int temps[5];
  temps[0] = 36;
  temps[1] = 37;
  temps[2] = 39;
  temps[3] = 35;
  temps[4] = 38;
  int sum = 0;
  for (int i = 0; i < 5; i++) {
    int shown = clamp(temps[i], 35, 40);
    sum = sum + shown;
    cout << "day " << (i + 1) << ": " << shown << endl;
  }
  cout << "average: " << (sum / 5) << endl;
  return 0;
}
`,
